package com.hbm.client.arcwelder;
import com.hbm.machine.arcwelder.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
@WailaPlugin public final class ArcWelderJadePlugin implements IWailaPlugin {
 @Override public void register(IWailaCommonRegistration event){event.registerBlockDataProvider(Provider.INSTANCE,ArcWelderBlockEntity.class);event.registerBlockDataProvider(Provider.INSTANCE,ArcWelderPort.class);}@Override public void registerClient(IWailaClientRegistration event){event.registerBlockComponent(Provider.INSTANCE,ArcWelderBlock.class);}
 private enum Provider implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider{INSTANCE;@Override public ResourceLocation getUid(){return ArcWelderContent.id("arcwelder_state");}@Override public void appendServerData(CompoundTag tag,BlockAccessor accessor){var tile=accessor.getBlockEntity();if(tile instanceof ArcWelderPort&&accessor.getBlockState().getBlock() instanceof ArcWelderBlock block){var pos=block.findCore(accessor.getLevel(),accessor.getPosition());tile=pos==null?null:accessor.getLevel().getBlockEntity(pos);}if(tile instanceof ArcWelderBlockEntity machine){tag.putLong("hbm:arcwelder_consumption",machine.consumption);}}@Override public void appendTooltip(ITooltip tooltip,BlockAccessor accessor,IPluginConfig config){var tag=accessor.getServerData();if(!tag.contains("hbm:arcwelder_consumption"))return;tooltip.add(Component.translatable("jade.hbm.arcwelder.consumption",tag.getLong("hbm:arcwelder_consumption")));}}
}
